            elseif($op==='import'&&$stepId==='result'){if(!is_array($s['imported']??null))throw new \RuntimeException('Import wurde noch nicht ausgeführt.');$data['moduleLibraryResult']=['action'=>'import','module'=>$s['imported']];$data['configurationReady']=true;}
            elseif(!in_array($op,['browse','create','import'],true)&&in_array($stepId,['select','configure','preview','apply','result'],true)){
                if(trim((string)($s['moduleLocator']??''))==='')throw new \RuntimeException('Modul fehlt.');[$v,$p,$id]=$this->locator((string)$s['moduleLocator']);$selected=$this->library->getScoped($id,$v,$p);if($selected===[])throw new \RuntimeException('Modul wurde nicht gefunden.');$data['selectedModule']=$selected;
                if($op==='install'){
                    $release=is_array($selected['release']??null)?$selected['release']:['version'=>'1.0.0','dependencies'=>[]];$gate=is_array($selected['releaseGate']??null)?$selected['releaseGate']:['status'=>'LEGACY_RELEASED','installable'=>true,'legacy'=>true];if(empty($gate['installable']))throw new \RuntimeException('Dieses Release ist nicht installierbar. Release-Gate-Status: '.(string)($gate['status']??'DRAFT').'. Bitte zuerst das Migrations-Gate / die Release-Freigabe ausführen.');if((array)($release['dependencies']??[])!==[])throw new \RuntimeException('Dieses Modul besitzt deklarierte Modulabhängigkeiten. Bitte "Modulabhängigkeiten und Installation" verwenden.');
