                    elseif($op==='export'){$q=['id'=>$id,'visibility'=>$v];if($p)$q['project_id']=$p;$data['moduleLibraryExportUrl']='module-library-download.php?'.http_build_query($q);}
                    elseif($op==='rename')$data['moduleLibraryResult']=['action'=>'rename','module'=>$this->library->rename($id,(string)($s['newName']??''),(string)($s['newDescription']??''),$v,$p)];
                    elseif($op==='copy'){[$tv,$tp]=$this->target($s,$c);$data['moduleLibraryResult']=['action'=>'copy','module'=>$this->library->copy($id,(string)($s['newName']??''),$v,$p,$tv,$tp)];}
