    private function merge(array $s,AssistantContext $c,string $step):array
    {
        if($step==='operation')return ['operation'=>(string)$c->input('operation','browse')];if($step==='select'){$s['moduleLocator']=trim((string)$c->input('module_locator',''));unset($s['installToken'],$s['applyResult']);}
        if($step==='configure'){$s['sourceProject']=trim((string)$c->input('source_project',$s['sourceProject']??($c->getProjectId()??'')));$s['newName']=trim((string)$c->input('new_name',$s['newName']??''));$s['newDescription']=trim((string)$c->input('new_description',$s['newDescription']??''));$s['rootDataForms']=(string)$c->input('root_dataforms',$s['rootDataForms']??($c->getDataFormId()??''));$s['includeTransitive']=$this->bool($c,'include_transitive');$s['includeDatasource']=$this->bool($c,'include_datasource');$s['targetVisibility']=(string)$c->input('target_visibility',$s['targetVisibility']??'project');$s['targetProject']=trim((string)$c->input('target_project',$s['targetProject']??($c->getProjectId()??'')));$s['deleteConfirmName']=trim((string)$c->input('delete_confirm_name',''));$s['confirmDelete']=$this->bool($c,'confirm_delete');$s['dataFormMapping']=(string)$c->input('dataform_mapping',$s['dataFormMapping']??'');$s['referenceMapping']=(string)$c->input('reference_mapping',$s['referenceMapping']??'');$s['allowOverwrite']=$this->bool($c,'allow_overwrite');$s['applyDatasource']=$this->bool($c,'apply_datasource');}
        if($step==='apply')$s['confirmApply']=$this->bool($c,'confirm_apply');return $s;
    }
    private function formValues(array $s,string $step,AssistantContext $c):array{return match($step){'operation'=>['operation'=>$s['operation']??'browse'],'select'=>['module_locator'=>$s['moduleLocator']??''],'configure'=>['source_project'=>$s['sourceProject']??($c->getProjectId()??''),'new_name'=>$s['newName']??'','new_description'=>$s['newDescription']??'','root_dataforms'=>$s['rootDataForms']??($c->getDataFormId()??''),'include_transitive'=>array_key_exists('includeTransitive',$s)?!empty($s['includeTransitive']):true,'include_datasource'=>array_key_exists('includeDatasource',$s)?!empty($s['includeDatasource']):true,'target_visibility'=>$s['targetVisibility']??'project','target_project'=>$s['targetProject']??($c->getProjectId()??''),'delete_confirm_name'=>$s['deleteConfirmName']??'','confirm_delete'=>!empty($s['confirmDelete']),'dataform_mapping'=>$s['dataFormMapping']??'','reference_mapping'=>$s['referenceMapping']??'','allow_overwrite'=>!empty($s['allowOverwrite']),'apply_datasource'=>!empty($s['applyDatasource'])],'apply'=>['confirm_apply'=>!empty($s['confirmApply'])],default=>[]};}
    /** @return array{0:string,1:?string} */private function target(array $s,AssistantContext $c):array{$v=(string)($s['targetVisibility']??'project');if(!in_array($v,['system','project'],true))throw new \InvalidArgumentException('Ungültige Zielfreigabe.');$p=$v==='project'?trim((string)($s['targetProject']??($c->getProjectId()??''))):null;if($v==='project'&&$p==='')throw new \InvalidArgumentException('Zielprojekt fehlt.');return[$v,$p];}
    /** @return array{0:string,1:?string,2:string} */private function locator(string $l):array{$p=explode('::',$l);if(($p[0]??'')==='system'&&isset($p[1]))return['system',null,$p[1]];if(($p[0]??'')==='project'&&isset($p[1],$p[2]))return['project',$p[1],$p[2]];throw new \InvalidArgumentException('Ungültige Modulauswahl.');}
    private function bool(AssistantContext $c,string $k):bool{return in_array($c->input($k,false),[true,1,'1','true','yes','on'],true);}private function next(array $ids,string $cur):?string{$i=array_search($cur,$ids,true);return $i!==false&&isset($ids[$i+1])?$ids[$i+1]:null;}private function prev(array $ids,string $cur):?string{$i=array_search($cur,$ids,true);return $i!==false&&$i>0?$ids[$i-1]:null;}
