    /** @return array<string,string> */private function mapping(string $t):array{$m=[];foreach(preg_split('/\R/',$t)?:[] as $line){$line=trim($line);if($line==='')continue;$p=array_map('trim',explode('|',$line,2));if(($p[0]??'')!==''&&isset($p[1])&&$p[1]!=='')$m[$p[0]]=$p[1];}return $m;}
